import requests
import json
from requests.exceptions import RequestException

def fetch_https_data(url):
    """
    Fetches data from an HTTPS endpoint and returns the response as JSON.

    Args:
        url (str): The HTTPS URL to fetch data from.

    Returns:
        dict: The JSON response data as a Python dictionary.

    Raises:
        ValueError: If the URL is not HTTPS or the response is not valid JSON.
        RequestException: If there is a connection error or other request-related error.
    """
    # Check if the URL starts with https
    if not url.startswith('https://'):
        raise ValueError("URL must be an HTTPS endpoint.")

    try:
        # Make the HTTPS GET request
        response = requests.get(url)
        response.raise_for_status()  # Raises an HTTPError for bad responses (4xx, 5xx)

        # Return the response data as JSON
        return response.json()

    except requests.exceptions.HTTPError as http_err:
        raise RequestException(f"HTTP error occurred: {http_err}")
    except requests.exceptions.ConnectionError as conn_err:
        raise RequestException(f"Connection error occurred: {conn_err}")
    except requests.exceptions.Timeout as timeout_err:
        raise RequestException(f"Timeout error occurred: {timeout_err}")
    except requests.exceptions.RequestException as req_err:
        raise RequestException(f"An error occurred during the request: {req_err}")
    except json.JSONDecodeError as json_err:
        raise ValueError(f"Failed to decode JSON response: {json_err}")

# Example usage
if __name__ == "__main__":
    try:
        data = fetch_https_data("https://api.example.com/data")
        print(data)
    except Exception as e:
        print(f"An error occurred: {e}")

import hashlib

def hash_operator_credential(credential: str) -> str:
    return hashlib.sha256(credential.encode()).hexdigest()

import secrets
import string

def generate_token(length=32):
    characters = string.ascii_letters + string.digits
    return ''.join(secrets.choice(characters) for _ in range(length))

