import requests
import json

def submit_generation_schedule(api_url, api_credentials, schedule_data):
    """
    Submits a generation schedule to the ISO/RTO market system.

    Args:
    - api_url (str): The URL of the market API.
    - api_credentials (dict): A dictionary containing the API credentials (e.g., username, password, or API key).
    - schedule_data (dict): A dictionary containing the generation schedule data.

    Returns:
    - A JSON response from the market API.
    """

    # Set API credentials
    headers = {
        'Content-Type': 'application/json',
        'Authorization': f"Bearer {api_credentials['api_key']}"  # Replace with your actual authentication method
    }

    # Convert schedule data to JSON
    schedule_json = json.dumps(schedule_data)

    try:
        # Connect to the market API and submit the generation schedule
        response = requests.post(api_url, headers=headers, data=schedule_json)

        # Check if the request was successful
        if response.status_code == 200:
            # Return the JSON response
            return response.json()
        else:
            # Return an error message
            return {'error': f"Failed to submit generation schedule. Status code: {response.status_code}"}
    except requests.exceptions.RequestException as e:
        # Return an error message if the request failed
        return {'error': f"Failed to connect to the market API. Error: {e}"}

# Example usage
if __name__ == "__main__":
    api_url = "https://example.com/market-api/schedule"
    api_credentials = {
        'api_key': "your_api_key_here"
    }
    schedule_data = {
        'generation_unit_id': 1,
        'schedule_date': "2024-09-16",
        'schedule_time': "08:00:00",
        'generation_mw': 100
    }

    result = submit_generation_schedule(api_url, api_credentials, schedule_data)
    print(json.dumps(result, indent=4))
